package main

import (
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	q := int(num())
	bit := make([]int, n+1)
	built := make([]bool, n)
	add := func(i int) {
		for i++; i <= n; i += i & -i {
			bit[i]++
		}
	}
	prefix := func(i int) int {
		s := 0
		for ; i > 0; i -= i & -i {
			s += bit[i]
		}
		return s
	}
	out := []byte{}
	for k := 0; k < q; k++ {
		op := token()
		if op == "build" {
			i := int(num())
			if !built[i] {
				built[i] = true
				add(i)
			}
		} else {
			l, r := int(num()), int(num())
			if len(out) > 0 {
				out = append(out, ' ')
			}
			if prefix(r+1)-prefix(l) > 0 {
				out = append(out, '1')
			} else {
				out = append(out, '0')
			}
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
